declare(strict_types=1);

namespace EinvoiceValidator\Tests\Unit\Xpath\Parser;

use EinvoiceValidator\Devkit\Xpath\Parser\Parser;
use EinvoiceValidator\Exception\UnsupportedConstructException;
use PHPUnit\Framework\TestCase;

/**
 * Every expression collected in docs/notes/xpath-inventory.md parses without error. Loads the full, untruncated
 * expression list (generated by devkit/Cli/inventory.php alongside the markdown report) and parses every one
 * of the 1956 real expressions from the actual EN16931/XRechnung rule sets - not a curated sample.
 */
final class ParserInventoryTest extends TestCase
{
    public function testEveryInventoriedExpressionParsesWithoutError(): void
    {
        $path = dirname(__DIR__, 3) . '/fixtures/xpath-inventory-expressions.json';
        self::assertFileExists($path, 'run `php devkit/Cli/inventory.php` first');

        $json = file_get_contents($path);
        self::assertIsString($json);
        /** @var list<string> $expressions */
        $expressions = json_decode($json, true, flags: JSON_THROW_ON_ERROR);
        self::assertGreaterThan(1900, count($expressions), 'sanity check: the fixture should hold ~1956 expressions');

        $failures = [];
        foreach ($expressions as $expr) {
            try {
                Parser::parse($expr);
            } catch (UnsupportedConstructException $e) {
                $failures[] = $e->getMessage();
            }
        }

        self::assertSame(
            [],
            $failures,
            sprintf("%d of %d expressions failed to parse:\n%s", count($failures), count($expressions), implode("\n", array_slice($failures, 0, 20)))
        );
    }
}
